import {EQUIPMENT_TEMPLATES} from './equipment-templates.js';
import {equipmentIcon} from './equipment-art.js';
import {BUILD,SET_SLOTS,SLOTNAME,LEGENDARY_CODEX,codexSetState,codexState} from './engine.js';
import {icon} from './icons.js';
const esc=t=>String(t??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const setImage=(setId,slot,size=48)=>equipmentIcon(EQUIPMENT_TEMPLATES.find(t=>t.setId===setId&&t.slot===slot)??{slot,set:setId,rarity:3},{size});
export function renderCodex(s,{tab='sets',selectedSet,selectedLegend}={}){
 const legends=tab==='legends';const nav=`<nav class="collectionTabs"><button data-codex-tab="sets" aria-pressed="${!legends}">${icon('helm')}套装印记</button><button data-codex-tab="legends" aria-pressed="${legends}">${icon('book')}传说遗物</button></nav>`;
 const foot='<p class="collectionFoot">图鉴记录曾经获得的物品；出售后仍保留记录。收集不增加角色属性。</p>';
 if(!legends){const b=BUILD.find(x=>x.id===selectedSet)||BUILD[0],state=codexSetState(s,b.id),parts=state.parts||[];return `<div class="panelPage collectionPage">${nav}<div class="collectionLayout"><div class="collectionGallery">${BUILD.map(x=>{const c=codexSetState(s,x.id);return `<button class="collectionTile ${c.discovered?'knownSet':'undiscoveredSet'} ${x.id===b.id?'collectionSelected':''}" data-codex-set="${x.id}">${setImage(x.id,'helm')}<strong>${x.name}</strong><small>${c.discovered?'曾收集 '+c.parts.length+' / 4':'未发现'}</small></button>`;}).join('')}</div><article class="collectionDetail"><div class="collectionHero ${state.discovered?'':'undiscoveredSet'}">${setImage(b.id,'armor',64)}</div><span class="eyebrow">THE OLD ARMORIES</span><h2>${b.name}</h2><span class="collectionBadge">${state.complete?'全套印记已收集':state.discovered?'曾收集 '+parts.length+' / 4 个部位':'尚未发现'}</span>${state.discovered?`<div class="collectedParts">${SET_SLOTS.map(slot=>`<div class="collectedPart ${parts.includes(slot)?'knownSet':'undiscoveredSet'}" title="${SLOTNAME[slot]} · ${parts.includes(slot)?'曾经获得':'未发现'}">${setImage(b.id,slot,32)}<span>${SLOTNAME[slot]}</span><small>${parts.includes(slot)?'已收集':'未发现'}</small></div>`).join('')}</div><div class="collectionEffects"><strong>穿戴套装效果</strong><p>${esc(b.bonus)}</p><small>仅穿戴对应件数时生效；图鉴数量不是当前装备数量。</small></div>`:'<p class="collectionUnknown">获得任意一个部位后，揭晓部位记录与套装效果。</p>'}</article></div>${foot}</div>`;}
 const entry=LEGENDARY_CODEX.find(x=>x.id===selectedLegend)||LEGENDARY_CODEX[0];if(!entry)return `<div class="panelPage collectionPage">${nav}<p>尚无遗物记录。</p>${foot}</div>`;const state=codexState(s,entry.id),known=!!state?.collected;return `<div class="panelPage collectionPage">${nav}<div class="collectionLayout"><div class="collectionGallery">${LEGENDARY_CODEX.map(x=>{const found=!!codexState(s,x.id)?.collected;return `<button class="collectionTile legendaryTile ${found?'':'unknownLegend'} ${x.id===entry.id?'collectionSelected':''}" data-codex-legend="${x.id}"><span class="relicShape">${found?equipmentIcon({legendaryId:x.id,rarity:3},{size:48}):icon(x.icon,'guard',4)}</span><strong>${found?esc(x.name):'未知遗物'}</strong><small>${found?'曾经获得':x.implemented?'尚未发现':'尚未实装'}</small></button>`;}).join('')}</div><article class="collectionDetail legendaryDetail ${known?'':'unknownLegend'}"><div class="collectionHero relicShape">${known?equipmentIcon({legendaryId:entry.id,rarity:3},{size:64}):icon(entry.icon,'guard',4)}</div><span class="eyebrow">RELICS OF THE LOST AGE</span><h2>${known?esc(entry.name):'未知遗物'}</h2><span class="collectionBadge">${known?'已收集':entry.implemented?'尚未发现':'尚未实装 · 目前无掉落'}</span>${known?`<p class="relicLore">${esc(entry.lore)}</p><p class="relicSlot">部位：${esc(SLOTNAME[entry.slot]||entry.slot)}</p>${entry.acquisition?`<p class="relicAcquisition">获取：${esc(entry.acquisition)}</p>`:''}${entry.attributes?`<p class="relicAttributes">${esc(entry.attributes)}</p>`:''}<div class="relicAffix" style="color:#e7bc58"><strong>${esc(entry.affix)}</strong><p>${esc(entry.effect)}</p>${entry.tuning?`<small>${esc(entry.tuning)}</small>`:''}</div>`:'<p class="collectionUnknown">未知的轮廓，尚未留下属于你的故事。</p>'}</article></div>${foot}</div>`;
}
